"""Pure, in-memory patch application. Nothing generated by the model is ever executed."""

import difflib
import hashlib

from app.schemas.incident import FileEdit


class PatchApplyError(Exception):
    pass


def apply_edits(files: dict[str, str | None], edits: list[FileEdit]) -> dict[str, str]:
    """files maps path -> current content (None if the file does not exist)."""
    result: dict[str, str] = {}
    for edit in edits:
        current = result.get(edit.path, files.get(edit.path))
        if edit.search == "":
            if current is not None:
                raise PatchApplyError(
                    f"{edit.path}: file exists; an empty 'search' only creates files."
                )
            result[edit.path] = edit.replace
            continue
        if current is None:
            raise PatchApplyError(f"{edit.path}: file was not found.")
        count = current.count(edit.search)
        if count != 1:
            raise PatchApplyError(
                f"{edit.path}: 'search' text matched {count} times (must match exactly once)."
            )
        result[edit.path] = current.replace(edit.search, edit.replace, 1)
    return result


def make_diff(before: dict[str, str | None], after: dict[str, str]) -> tuple[str, int]:
    """Unified diff (git-apply compatible headers) and number of added+removed lines."""
    chunks: list[str] = []
    changed = 0
    for path, new in after.items():
        old = before.get(path)
        diff = list(
            difflib.unified_diff(
                (old or "").splitlines(keepends=True),
                new.splitlines(keepends=True),
                fromfile="/dev/null" if old is None else f"a/{path}",
                tofile=f"b/{path}",
            )
        )
        changed += sum(
            1 for line in diff if line[0] in "+-" and not line.startswith(("+++", "---"))
        )
        for line in diff:
            chunks.append(
                line if line.endswith("\n") else line + "\n\\ No newline at end of file\n"
            )
    return "".join(chunks), changed


def patch_hash(edits: list[FileEdit]) -> str:
    h = hashlib.sha256()
    for e in edits:
        for part in (e.path, e.search, e.replace):
            h.update(part.encode())
            h.update(b"\x00")
    return h.hexdigest()
